          : bookArchive(ledger, op);
      case "import":
        return ledger.post(booking(op));
      case "cancel":
        return ledger.cancel(name(op.id, "id"));
      case "lookup":
        return ledger.inspect(name(op.id, "id"));
      case "usage":
        return {units: ledger.usage(name(op.tenant, "tenant"), day(op.day))};
